function createRow(e,t,n,a){const o=Number(n).toLocaleString("en-PH",{style:"currency",currency:"PHP"}),r=`\n            <tr class="fade-in-up z-10 text-gray-800 bg-gray-50 dark:bg-white/2 hover:bg-black/5 dark:hover:bg-white/5 dark:text-gray-100 border-b border-gray-300 dark:border-gray-700">\n                  <td class="px-6 py-4 text-center whitespace-nowrap">${e}</td>\n                  <td class="px-6 py-4 text-center  whitespace-nowrap">${Number(t).toLocaleString("en-PH",{style:"currency",currency:"PHP"})}</td>\n                  <td class="px-6 py-4 text-center  whitespace-nowrap">${o}</td>\n                  <td class="px-6 py-4 text-center  whitespace-nowrap">${Number(a).toLocaleString("en-PH",{style:"currency",currency:"PHP"})}</td>\n            </tr>\n      `;document.getElementById("accounting-tbody").innerHTML+=r}function removePrevRow(){document.querySelectorAll("#accounting-tbody tr").forEach(e=>e.remove())}function formatPesoShort1(e){return e>=1e9?"₱"+(e/1e9).toFixed(1).replace(/\.0$/,"")+"B":e>=1e6?"₱"+(e/1e6).toFixed(1).replace(/\.0$/,"")+"M":e>=1e3?"₱"+(e/1e3).toFixed(1).replace(/\.0$/,"")+"K":"₱"+e.toLocaleString("en-PH")}async function getYearNow(){const e=await fetch("/get-years");(await e.json()).years.forEach(e=>{const t=document.createElement("option");t.value=e.year,t.textContent=e.year,e.year===(new Date).getFullYear()&&(t.selected=!0),document.getElementById("filter-payment").appendChild(t)})}async function getSummaryData(){const e=await fetch("/accounting-data"),t=await e.json();document.getElementById("direct-payment").textContent=formatPesoShort1(Number(t.direct)),document.getElementById("online-payment").textContent=formatPesoShort1(Number(t.online)),document.getElementById("booking-revenue").textContent=formatPesoShort1(Number(t.total_revenue))}async function loadBookingRevenue(e){const t=await fetch(`/load-revenue?year=${e}`),n=await t.json();console.log(n),n.success?(removePrevRow(),n.data.forEach(e=>{createRow(e.month_name,e.direct,e.online,e.total)})):alert("Failed to fetch data.")}document.addEventListener("change",e=>{e.target.matches("#filter-payment")&&loadBookingRevenue(e.target.value)}),getYearNow();export function initPageAccounting(){getSummaryData(),loadBookingRevenue("2025")}